    """Subtract interval [b_start, b_end) from all intervals."""
    result = []

    for start, end in intervals:
        # No overlap
        if end <= b_start or start >= b_end:
            result.append([start, end])
        else:
            # There is overlap
            # Add the part before b_start
            if start < b_start:
                result.append([start, b_start])
            # Add the part after b_end
            if end > b_end:
                result.append([b_end, end])

    return result

